SELECT st_sub.student_id,st_sub.student_name,st_sub.subject_name,count(exam.subject_name) as attended_exams FROM (SELECT * from Students CROSS JOIN Subjects) st_sub LEFT JOIN Examinations exam ON st_sub.student_id=exam.student_id AND st_sub.subject_name = exam.subject_name group by st_sub.student_id,st_sub.student_name,st_sub.subject_name order by st_sub.student_id,st_sub.subject_name;